<script setup>
import { ref, watch } from 'vue'
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const localize = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const searchChanged = (event) => emit('update:searchQuery', event.target.value)
const activeProductTab = ref('details')
const quantity = ref(1)

watch(() => props.product?.id, () => {
  activeProductTab.value = 'details'
  quantity.value = 1
})

const isPantryItem = (product) =>
  product?.category === 'home' || /pantry|household|linen/.test(String(product?.id || ''))
const laneLabel = (product) => isPantryItem(product)
  ? localize('常温与居家', 'PANTRY & HOME')
  : localize('保存方式待确认', 'STORAGE TO CONFIRM')
</script>

<template>
  <main class="kurly-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
    <header class="kp-bar">
      <button type="button" :aria-label="localize('返回', 'Back')" @click="emit('back')"><i class="fas fa-arrow-left"></i></button>
      <strong>Kurly</strong>
      <div><button type="button" :aria-label="localize('订单', 'Orders')" @click="emit('open-orders')"><i class="fas fa-receipt"></i></button><button type="button" data-testid="shopping-page-cart" :aria-label="localize('购物篮', 'Basket')" @click="emit('open-cart')"><i class="fas fa-basket-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div>
    </header>

    <template v-if="pageKey === 'category'">
      <section class="kp-category-intro">
        <div><small>MARKET AISLE</small><h1>{{ category?.label || localize('全部商品', 'All products') }}</h1><p>{{ favoritesOnly ? localize('你保存下来、准备稍后再看的商品。', 'Items saved for another table.') : localize('先选商品，再在结算页确认配送条件。', 'Choose items first; confirm delivery at checkout.') }}</p></div>
        <span><b>{{ totalCount }}</b>{{ localize('件商品', 'ITEMS') }}</span>
      </section>

      <form class="kp-search" @submit.prevent="emit('submit-search')"><i class="fas fa-magnifying-glass"></i><input type="search" :value="searchQuery" :placeholder="localize('搜索商品名称或用途', 'Search by item or use')" @input="searchChanged" /><button type="submit">{{ localize('搜索', 'Search') }}</button></form>
      <nav class="kp-categories" :aria-label="localize('商品分类', 'Categories')"><button v-for="item in categories" :key="item.key" type="button" :class="{ active: item.key === category?.key }" @click="emit('select-category', item.key)"><span>{{ item.label }}</span><small>{{ item.count }}</small></button></nav>

      <section v-if="!products.length" class="kp-empty"><i class="fas fa-seedling"></i><strong>{{ localize('没有找到商品', 'No items found') }}</strong><p>{{ localize('请更换关键词或分类。', 'Try another search or category.') }}</p></section>
      <section v-else class="kp-grid">
        <article v-for="product in products" :key="product.id" :data-testid="`shopping-product-${product.id}`">
          <button type="button" class="kp-media" @click="emit('open-product', product.id)"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><span v-else><i :class="productCategoryIcon(product)"></i></span><em>{{ laneLabel(product) }}</em></button>
          <button type="button" class="kp-save" :class="{ active: isProductFavorite(product.id) }" :aria-label="localize('收藏或取消收藏', 'Toggle favorite')" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart"></i></button>
          <button type="button" class="kp-copy" @click="emit('open-product', product.id)"><small>{{ stockStatusLabel(product.stockStatus) }}</small><strong>{{ productDisplayTitle(product) }}</strong><p>{{ productDisplayDescription(product) }}</p></button>
          <footer><strong>{{ formatPrice(product) }}</strong><button type="button" :disabled="product.stockStatus === 'sold_out'" :aria-label="`${localize('加入购物篮', 'Add to basket')}: ${productDisplayTitle(product)}`" @click="emit('add-to-cart', product.id)"><i class="fas fa-basket-shopping"></i></button></footer>
        </article>
      </section>
      <nav v-if="pageCount > 1" class="kp-pagination" data-testid="shopping-pagination"><button type="button" :disabled="page <= 1" @click="emit('change-page', page - 1)"><i class="fas fa-arrow-left"></i>{{ localize('上一页', 'Previous') }}</button><span>{{ page }} / {{ pageCount }}</span><button type="button" :disabled="page >= pageCount" @click="emit('change-page', page + 1)">{{ localize('下一页', 'Next') }}<i class="fas fa-arrow-right"></i></button></nav>
    </template>

    <template v-else-if="product">
      <section class="kp-pdp">
        <div class="kp-pdp-media"><img v-if="productImageUrl(product)" :src="productImageUrl(product)" :alt="productDisplayTitle(product)" /><span v-else><i :class="productCategoryIcon(product)"></i></span><button type="button" :class="{ active: isProductFavorite(product.id) }" :aria-label="localize('收藏或取消收藏', 'Toggle favorite')" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart"></i></button></div>
        <div class="kp-pdp-buy"><small>{{ laneLabel(product) }}</small><h1>{{ productDisplayTitle(product) }}</h1><p>{{ productDisplayDescription(product) }}</p><strong>{{ formatPrice(product) }}</strong><dl><div><dt>{{ localize('库存状态', 'Availability') }}</dt><dd>{{ stockStatusLabel(product.stockStatus) }}</dd></div><div><dt>{{ localize('配送条件', 'Delivery') }}</dt><dd>{{ localize('结算时确认', 'Confirmed at checkout') }}</dd></div><div><dt>{{ localize('包装分组', 'Packing group') }}</dt><dd>{{ isPantryItem(product) ? localize('常温与居家商品', 'Pantry and home items') : localize('按商品说明核对', 'Review item guidance') }}</dd></div></dl><div class="kp-quantity"><button type="button" :disabled="quantity <= 1" @click="quantity -= 1">−</button><span>{{ quantity }}</span><button type="button" @click="quantity += 1">+</button></div><button type="button" data-testid="shopping-product-add" :disabled="product.stockStatus === 'sold_out'" @click="emit('add-to-cart', product.id, quantity)">{{ localize('加入购物篮', 'Add to basket') }} · {{ quantity }}</button></div>
      </section>

      <nav class="kp-pdp-tabs" :aria-label="localize('商品信息', 'Product information')"><button type="button" :class="{ active: activeProductTab === 'details' }" @click="activeProductTab = 'details'">{{ localize('商品详情', 'Details') }}</button><button type="button" :class="{ active: activeProductTab === 'reviews' }" @click="activeProductTab = 'reviews'">{{ localize('用户评价', 'Reviews') }}</button><button type="button" :class="{ active: activeProductTab === 'delivery' }" @click="activeProductTab = 'delivery'">{{ localize('配送与保存', 'Delivery') }}</button></nav>

      <section v-if="activeProductTab === 'details'" class="kp-tab-panel kp-details"><header><small>PRODUCT NOTES</small><h2>{{ localize('购买前需要知道的', 'What to know before buying') }}</h2></header><div><article><i class="fas fa-box-open"></i><strong>{{ localize('商品说明', 'Item description') }}</strong><p>{{ productDisplayDescription(product) }}</p></article><article><i class="fas fa-tags"></i><strong>{{ localize('分类', 'Category') }}</strong><p>{{ category?.label || product.category }}</p></article><article><i class="fas fa-circle-check"></i><strong>{{ localize('当前状态', 'Current status') }}</strong><p>{{ stockStatusLabel(product.stockStatus) }}</p></article></div></section>

      <section v-else-if="activeProductTab === 'reviews'" class="kp-tab-panel kp-reviews"><header><small>BUYER REVIEWS</small><h2>{{ localize('用户评价', 'Customer reviews') }}</h2></header><div class="kp-review-empty"><i class="fas fa-message"></i><strong>{{ localize('这个商品还没有评价', 'No reviews yet') }}</strong><p>{{ localize('暂时还没有买家评分或实拍图片，可以先查看商品详情与配送说明。', 'There are no buyer ratings or photos yet. Check the product details and delivery information first.') }}</p></div></section>

      <section v-else class="kp-tab-panel kp-delivery"><header><small>DELIVERY & STORAGE</small><h2>{{ localize('配送和收纳说明', 'Delivery and storage') }}</h2></header><div><article><span>01</span><strong>{{ localize('配送时间', 'Delivery timing') }}</strong><p>{{ localize('具体时段在结算与订单记录中确认。', 'The actual window is confirmed in checkout and order records.') }}</p></article><article><span>02</span><strong>{{ localize('包装方式', 'Packing') }}</strong><p>{{ localize('生鲜与常温商品在结算页分组核对。', 'Fresh and pantry items are grouped during checkout review.') }}</p></article><article><span>03</span><strong>{{ localize('保存建议', 'Storage guidance') }}</strong><p>{{ localize('以商品包装与订单中的真实说明为准。', 'Follow the item packaging and recorded order guidance.') }}</p></article></div></section>

      <section class="kp-related"><header><small>COMPLETE THE TABLE</small><h2>{{ localize('一起买更方便', 'Complete the basket') }}</h2></header><div><button v-for="item in relatedProducts.slice(0, 4)" :key="item.id" type="button" @click="emit('open-product', item.id)"><span><img v-if="productImageUrl(item)" :src="productImageUrl(item)" :alt="productDisplayTitle(item)" /><i v-else :class="productCategoryIcon(item)"></i></span><strong>{{ productDisplayTitle(item) }}</strong><small>{{ formatPrice(item) }}</small></button></div></section>
    </template>
  </main>
</template>

<style scoped>
.kurly-pages{--purple:#5f0080;--deep:#2f0a3b;--lime:#c7df5b;--ink:#211526;--muted:#756b79;--line:#e8e1ea;min-height:100%;color:var(--ink);background:#fff;font-family:"Noto Sans KR",Arial,sans-serif}.kp-bar{position:sticky;top:0;z-index:20;height:58px;padding:0 16px;display:grid;grid-template-columns:40px 1fr auto;align-items:center;border-bottom:1px solid var(--line);background:rgba(255,255,255,.97);backdrop-filter:blur(12px)}.kp-bar>strong{color:var(--purple);font:700 20px Georgia,serif}.kp-bar>div{display:flex}.kp-bar button{position:relative;width:40px;height:40px}.kp-bar b{position:absolute;top:1px;right:1px;min-width:16px;height:16px;display:grid;place-items:center;border-radius:9px;color:#fff;background:var(--purple);font-size:8px}.kp-category-intro{padding:32px 20px 25px;display:flex;align-items:end;justify-content:space-between;gap:16px;color:#fff;background:var(--deep)}.kp-category-intro small,.kp-tab-panel header small,.kp-related header small{color:var(--lime);font-size:8px;font-weight:900;letter-spacing:.13em}.kp-category-intro h1{margin:8px 0 0;font:700 40px/1 Georgia,"Noto Serif KR",serif}.kp-category-intro p{max-width:42ch;margin:12px 0 0;color:rgba(255,255,255,.68);font-size:9px}.kp-category-intro>span{padding-left:18px;border-left:1px solid rgba(255,255,255,.24);font-size:8px}.kp-category-intro b{display:block;color:var(--lime);font:700 38px Georgia,serif}.kp-search{height:46px;margin:16px 20px 12px;padding-left:13px;display:grid;grid-template-columns:20px 1fr auto;align-items:center;border:1px solid var(--purple);border-radius:7px}.kp-search input{min-width:0;border:0;outline:0;font-size:11px}.kp-search button{height:34px;margin-right:5px;padding:0 13px;color:#fff;background:var(--purple);font-size:8px;font-weight:900}.kp-categories{padding:0 20px 16px;display:flex;gap:18px;overflow-x:auto;border-bottom:1px solid var(--line)}.kp-categories button{padding:8px 0;display:flex;gap:5px;border-bottom:2px solid transparent;color:var(--muted);font-size:9px