nt-size:9px}.kp-pdp{display:grid;grid-template-columns:1.08fr .92fr;min-height:590px}.kp-pdp-media{position:relative;min-height:590px;overflow:hidden;background:#eee8f0}.kp-pdp-media img{width:100%;height:100%;object-fit:cover}.kp-pdp-media>span{height:100%;display:grid;place-items:center;color:var(--purple);font-size:72px}.kp-pdp-media button{position:absolute;top:18px;right:18px;width:42px;height:42px;border-radius:50%;color:#aaa;background:#fff}.kp-pdp-media button.active{color:var(--purple)}.kp-pdp-buy{padding:42px 32px;display:flex;flex-direction:column;justify-content:center}.kp-pdp-buy>small{color:var(--purple);font-size:8px;font-weight:900;letter-spacing:.11em}.kp-pdp-buy h1{margin:10px 0 0;font:700 40px/1.08 Georgia,"Noto Serif KR",serif}.kp-pdp-buy>p{margin:14px 0 0;color:var(--muted);font-size:10px;line-height:1.7}.kp-pdp-buy>strong{margin-top:19px;font-size:19px}.kp-pdp-buy dl{margin:20px 0 14px;border-top:1px solid var(--line)}.kp-pdp-buy dl div{padding:10px 0;display:grid;grid-template-columns:1fr 1.4fr;border-bottom:1px solid var(--line);font-size:9px}.kp-pdp-buy dt{color:var(--muted)}.kp-pdp-buy dd{margin:0;font-weight:800}.kp-quantity{width:112px;height:38px;margin-bottom:9px;display:grid;grid-template-columns:38px 1fr 38px;border:1px solid var(--line)}.kp-quantity>*{display:grid;place-items:center}.kp-pdp-buy>button{height:50px;color:#fff;background:var(--purple);font-size:10px;font-weight:900}.kp-pdp-buy>button:disabled{opacity:.35}.kp-pdp-tabs{position:sticky;top:58px;z-index:10;display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#fff}.kp-pdp-tabs button{height:49px;color:var(--muted);font-size:9px;font-weight:800}.kp-pdp-tabs button.active{color:var(--purple);box-shadow:inset 0 -3px var(--purple)}.kp-tab-panel{padding:42px 22px;background:#f8f6f8}.kp-tab-panel header h2,.kp-related header h2{margin:6px 0 0;font:700 29px Georgia,"Noto Serif KR",serif}.kp-details>div,.kp-